#define main validate_df32_main_disabled
#include "validate_df32.cu"
#undef main

struct QParam {Param p;double lo,hi,x0;};
struct QOutput {double root,residual,gradient,condition;uint32_t iterations;uint8_t status,pad[3];};
__device__ __forceinline__ void qres(const QParam&q,double x,double&y,double&dy){
  if(q.p.domain!=CSTR){residual(q.p,x,y,dy);return;}double den=q.p.b+q.p.c*x,lr=log(q.p.a)+q.p.b*q.p.c*x/den,sig;if(lr>=0){double t=exp(-lr);sig=1/(1+t);}else{double t=exp(lr);sig=t/(1+t);}double ep=q.p.b*q.p.b*q.p.c/(den*den);y=x-sig;dy=1-sig*(1-sig)*ep;
}
__device__ __forceinline__ bool qbracket(const QParam&q,double&a,double&b){
  a=q.lo;b=q.hi;if(q.p.domain!=CSTR&&q.p.domain!=PR)return true;
  if(q.p.domain==PR){double cc=q.p.a-3*q.p.b*q.p.b-2*q.p.b,u=1-q.p.b,disc=4*u*u-12*cc,pts[4];int np=0;pts[np++]=a;if(disc>0){double sd=sqrt(disc),x1=(2*u-sd)/6,x2=(2*u+sd)/6;if(x1>a&&x1<b)pts[np++]=x1;if(x2>a&&x2<b)pts[np++]=x2;}pts[np++]=b;double fp,df,firsta=a,firstb=b,lasta=a,lastb=b;qres(q,pts[0],fp,df);int found=0;for(int k=1;k<np;k++){double fz;qres(q,pts[k],fz,df);if((fp<=0&&fz>=0)||(fp>=0&&fz<=0)){if(!found){firsta=pts[k-1];firstb=pts[k];}lasta=pts[k-1];lastb=pts[k];found++;}fp=fz;}if(!found)return false;a=q.p.branch?lasta:firsta;b=q.p.branch?lastb:firstb;return true;}
  double prev=a,fp,df,firsta=a,firstb=b,lasta=a,lastb=b;qres(q,prev,fp,df);int found=0;for(int s=1;s<=256;s++){double z=a+(b-a)*s/256,fz;qres(q,z,fz,df);if((fp<=0&&fz>=0)||(fp>=0&&fz<=0)){if(!found){firsta=prev;firstb=z;}lasta=prev;lastb=z;found++;}prev=z;fp=fz;}if(!found)return false;a=q.p.branch?lasta:firsta;b=q.p.branch?lastb:firstb;return true;
}
__device__ __forceinline__ double qsolve(const QParam&q,uint32_t&used){double a,b;if(!qbracket(q,a,b)){used=0;return NAN;}double fa,fb,df;qres(q,a,fa,df);qres(q,b,fb,df);double x=q.x0;if(x<=a||x>=b)x=.5*(a+b);used=0;for(int k=0;k<52;k++){double f,fx;qres(q,x,f,fx);if((fa<=0&&f>=0)||(fa>=0&&f<=0)){b=x;fb=f;}else{a=x;fa=f;}double step=f/fx;if(fabs(step)<1e-13){used++;break;}double z=x-step;if(!isfinite(z)||z<=a||z>=b)z=.5*(a+b);x=z;used++;}return x;}
__device__ __forceinline__ QOutput qfinish(const QParam&q,double x,uint32_t it){double y,dy;qres(q,x,y,dy);double fp;if(q.p.domain==BEM){double s=sin(x),c=cos(x),cl=q.p.d*(x-q.p.c),ct=cl*s-q.p.e*c;fp=c/(q.p.a*q.p.a)-q.p.b*ct/(4*s*q.p.a*q.p.a);}else if(q.p.domain==KEPLER)fp=-1;else if(q.p.domain==PV){double ez=exp(clampv((q.p.b+x*q.p.e)/q.p.d,-80.0,80.0));fp=q.p.c*ez/q.p.d+1/q.p.f;}else if(q.p.domain==CSTR){double den=q.p.b+q.p.c*x,lr=log(q.p.a)+q.p.b*q.p.c*x/den,sig;if(lr>=0){double t=exp(-lr);sig=1/(1+t);}else{double t=exp(lr);sig=t/(1+t);}fp=-sig*(1-sig)/q.p.a;}else fp=x-q.p.b;QOutput o{};o.root=x;o.residual=fabs(y);o.gradient=-fp/dy;o.condition=1/fmax(fabs(dy),1e-300);o.iterations=it;o.status=(!isfinite(x)||!isfinite(o.gradient))?ROOT_NONFINITE:ROOT_OK;return o;}
__global__ void kernel_fp64_equiv(const QParam*p,QOutput*o,size_t n){size_t i=(size_t)blockIdx.x*blockDim.x+threadIdx.x;if(i>=n)return;uint32_t it;double x=qsolve(p[i],it);o[i]=qfinish(p[i],x,it);}

static DParam to_dp(const Param&p){double lo,hi,x0;bounds(p,lo,hi,x0);DParam d{};for(int k=0;k<6;k++)((&d.a)[k])=host_d32((&p.a)[k]);d.lo=host_d32(lo);d.hi=host_d32(hi);d.x0=host_d32(x0);d.domain=p.domain;d.branch=p.branch;return d;}static QParam to_qp(const Param&p){double lo,hi,x0;bounds(p,lo,hi,x0);return {p,lo,hi,x0};}
static int inner_df(size_t n){return n<2048?100:(n<32768?10:1);}
template<class F>static std::vector<double> evt(F launch,int inner,int warm,int reps,cudaStream_t st){for(int k=0;k<warm;k++)launch();cudaStreamSynchronize(st);cudaEvent_t a,b;cudaEventCreate(&a);cudaEventCreate(&b);std::vector<double>v;for(int r=0;r<reps;r++){cudaEventRecord(a,st);for(int k=0;k<inner;k++)launch();cudaEventRecord(b,st);cudaEventSynchronize(b);float ms;cudaEventElapsedTime(&ms,a,b);v.push_back(ms/inner);}cudaEventDestroy(a);cudaEventDestroy(b);return v;}
int main(int argc,char**argv){std::string outdir="results_raw/df32_performance";size_t maxn=2097152;int reps=30,warm=10,heat=30;for(int i=1;i<argc;i++){if(!strcmp(argv[i],"--out"))outdir=argv[++i];else if(!strcmp(argv[i],"--max-n"))maxn=strtoull(argv[++i],nullptr,10);else if(!strcmp(argv[i],"--repetitions"))reps=atoi(argv[++i]);else if(!strcmp(argv[i],"--warmups"))warm=atoi(argv[++i]);else if(!strcmp(argv[i],"--heat-seconds"))heat=atoi(argv[++i]);}std::filesystem::create_directories(outdir);std::ofstream sum(outdir+"/df32_performance.csv"),raw(outdir+"/df32_performance_repetitions.csv");sum<<"domain,n,method,kernel_median_ms,e2e_median_ms,kernel_mroots_s,e2e_mroots_s,root_diff_p99,root_diff_max,wrong_root,iterations_p99,checksum\n";raw<<"domain,n,method,timing_kind,repetition,value_ms\n";cudaStream_t st;cudaStreamCreate(&st);size_t hn=1<<18;std::vector<Param>base(hn);std::vector<DParam>heat_params(hn);for(size_t i=0;i<hn;i++){base[i]=make_param(KEPLER,i);heat_params[i]=to_dp(base[i]);}DParam*td;DOutput*to;cudaMalloc(&td,hn*sizeof(DParam));cudaMalloc(&to,hn*sizeof(DOutput));cudaMemcpy(td,heat_params.data(),hn*sizeof(DParam),cudaMemcpyHostToDevice);double hs=omp_get_wtime();while(omp_get_wtime()-hs<heat)kernel_df32<<<int((hn+255)/256),256,0,st>>>(td,to,hn);cudaStreamSynchronize(st);cudaFree(td);cudaFree(to);
  const char*dn[]={"bem","kepler","pv","cstr","peng_robinson"};const char*mn[]={"df32","fp64_equivalent"};std::vector<size_t>ns={1,8,32,128,512,2048,8192,32768,131072,524288,2097152,8388608,16777216};for(int dom=0;dom<5;dom++)for(size_t n:ns){if(n>maxn)continue;std::vector<DParam>dpv(n);std::vector<QParam>qpv(n);std::vector<DOutput>dho(n);std::vector<QOutput>qho(n);for(size_t i=0;i<n;i++){Param p=make_param(dom,i);dpv[i]=to_dp(p);qpv[i]=to_qp(p);}cudaHostRegister(dpv.data(),n*sizeof(DParam),0);cudaHostRegister(qpv.data(),n*sizeof(QParam),0);cudaHostRegister(dho.data(),n*sizeof(DOutput),0);cudaHostRegister(qho.data(),n*sizeof(QOutput),0);DParam*dd;DOutput*dout;QParam*qd;QOutput*qout;cudaMalloc(&dd,n*sizeof(DParam));cudaMalloc(&dout,n*sizeof(DOutput));cudaMalloc(&qd,n*sizeof(QParam));cudaMalloc(&qout,n*sizeof(QOutput));cudaMemcpy(dd,dpv.data(),n*sizeof(DParam),cudaMemcpyHostToDevice);cudaMemcpy(qd,qpv.data(),n*sizeof(QParam),cudaMemcpyHostToDevice);int blocks=int((n+255)/256),inner=inner_df(n);std::vector<double>kt[2],et[2];for(int oi=0;oi<2;oi++){int m=(int(n/8)+dom+oi)&1;if(m==0){auto launch=[&](){kernel_df32<<<blocks,256,0,st>>>(dd,dout,n);};kt[m]=evt(launch,inner,warm,reps,st);auto e2e=[&](){cudaMemcpyAsync(dd,dpv.data(),n*sizeof(DParam),cudaMemcpyHostToDevice,st);kernel_df32<<<blocks,256,0,st>>>(dd,dout,n);cudaMemcpyAsync(dho.data(),dout,n*sizeof(DOutput),cudaMemcpyDeviceToHost,st);};et[m]=evt(e2e,n<2048?10:1,warm,reps,st);}else{auto launch=[&](){kernel_fp64_equiv<<<blocks,256,0,st>>>(qd,qout,n);};kt[m]=evt(launch,inner,warm,reps,st);auto e2e=[&](){cudaMemcpyAsync(qd,qpv.data(),n*sizeof(QParam),cudaMemcpyHostToDevice,st);kernel_fp64_equiv<<<blocks,256,0,st>>>(qd,qout,n);cudaMemcpyAsync(qho.data(),qout,n*sizeof(QOutput),cudaMemcpyDeviceToHost,st);};et[m]=evt(e2e,n<2048?10:1,warm,reps,st);}for(int r=0;r<reps;r++){raw<<dn[dom]<<','<<n<<','<<mn[m]<<",kernel,"<<r<<','<<std::setprecision(12)<<kt[m][r]<<'\n';raw<<dn[dom]<<','<<n<<','<<mn[m]<<",e2e,"<<r<<','<<et[m][r]<<'\n';}}
    kernel_df32<<<blocks,256,0,st>>>(dd,dout,n);kernel_fp64_equiv<<<blocks,256,0,st>>>(qd,qout,n);cudaMemcpyAsync(dho.data(),dout,n*sizeof(DOutput),cudaMemcpyDeviceToHost,st);cudaMemcpyAsync(qho.data(),qout,n*sizeof(QOutput),cudaMemcpyDeviceToHost,st);cudaStreamSynchronize(st);size_t check=std::min(n,size_t(100000));std::vector<double>diff,itd,itq;size_t wrong=0;double csd=0,csq=0;for(size_t i=0;i<check;i++){double x=hd(dho[i].root),e=fabs(x-qho[i].root);diff.push_back(e);wrong+=e>1e-7;itd.push_back(dho[i].iterations);itq.push_back(qho[i].iterations);csd+=x*(1+i%17);csq+=qho[i].root*(1+i%17);}for(int m=0;m<2;m++){double km=median(kt[m]),em=median(et[m]);sum<<dn[dom]<<','<<n<<','<<mn[m]<<','<<std::setprecision(12)<<km<<','<<em<<','<<n/km/1000<<','<<n/em/1000<<','<<quantile(diff,.99)<<','<<*max_element(diff.begin(),diff.end())<<','<<wrong<<','<<quantile(m?itq:itd,.99)<<','<<(m?csq:csd)<<'\n';printf("%-14s N=%9zu %-16s kernel=%9.4f e2e=%9.4f diff=%.2e wrong=%zu\n",dn[dom],n,mn[m],km,em,*max_element(diff.begin(),diff.end()),wrong);}raw.flush();sum.flush();cudaFree(dd);cudaFree(dout);cudaFree(qd);cudaFree(qout);cudaHostUnregister(dpv.data());cudaHostUnregister(qpv.data());cudaHostUnregister(dho.data());cudaHostUnregister(qho.data());}cudaStreamDestroy(st);return 0;}
